 "content": "def transform(grid):
    """Extend each colored center of a 3-marked cardinal cross across its row and column."""
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    centers = []
    for r in range(h):
        for c in range(w):
            color = original[r][c]
            if color == 0 or color == 3:
                continue
            if (r > 0 and r + 1 < h and c > 0 and c + 1 < w
                    and original[r-1][c] == 3 and original[r+1][c] == 3
                    and original[r][c-1] == 3 and original[r][c+1] == 3):
                centers.append((r, c, color))

    out = [row[:] for row in original]
    # Paint horizontal beams first, then vertical beams. Original nonzero cells
    # (including the 3 markers and colored centers) remain untouched; vertical
    # beams take precedence over horizontal beams at newly painted crossings.
    for r, c, color in centers:
        for x in range(w):
            if original[r][x] == 0:
                out[r][x] = color
    for r, c, color in centers:
        for y in range(h):
            if original[y][c] == 0:
                out[y][c] = color
            elif out[y][c] != 3 and original[y][c] == 0:
                out[y][c] = color
    return out

if __name__ == '__main__':
    # Demonstration geometry: colored crosses at (3,5)=2, (4,20)=6,
    # and (21,22)=8; the uncolored cross at (18,13) emits no beam.
    g = [[0] * 30 for _ in range(30)]
    for r, c, col in [(3, 5, 2), (4, 20, 6), (21, 22, 8)]:
        g[r][c] = col
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            g[r+dr][c+dc] = 3
    for r, c in [(18,13)]:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            g[r+dr][c+dc] = 3
    o = transform(g)
    assert len(o) == 30 and all(len(row) == 30 for row in o)
    assert o[21][20] == 6  # vertical beam wins at the 8/6 crossing
    assert o[3][20] == 3 and o[4][5] == 3  # original markers are preserved
    assert o[17][13] == 3 and o[18][12] == 3  # uncolored cross remains
    assert o[0][5] == 2 and o[29][22] == 8 and o[0][20] == 6
    print('demo geometry checks passed')
    test = [[0]*19 for _ in range(19)]
    crosses = [(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
    for r,c,col in crosses:
        test[r][c] = col
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            test[r+dr][c+dc] = 3
    result = transform(test)
    for row in result:
        print(' '.join(map(str,row)))
    assert result[3][6] == 8 and result[4][13] == 4
    assert result[12][14] == 1 and result[14][3] == 2
    print('test geometry checks passed')
",
 "cross_profile": false
}

