 "content": "def transform(grid):
    """Colored 3-crosses project colored lines; adjacent 3s remain barriers."""
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = src[r][c]
            if color not in (0, 3) and src[r-1][c] == src[r+1][c] == src[r][c-1] == src[r][c+1] == 3:
                centers.append((r, c, color))

    out = [row[:] for row in src]
    # For every cross, scan each ray from its center to the edge. Any 3 stops
    # that ray (including the cross's own adjacent 3), while zeros are painted.
    # Thus all four immediate 3 markers are preserved and block outgoing rays.
    for r, c, color in centers:
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            y, x = r + dr, c + dc
            while 0 <= y < h and 0 <= x < w:
                if src[y][x] == 3:
                    break
                if src[y][x] == 0:
                    out[y][x] = color
                y += dr
                x += dc
    return out

if __name__ == '__main__':
    # Demo 3 representative outputs: each beam is drawn only outwards from
    # its center, stopping at the first of the center's surrounding 3 cells.
    test = [[0] * 19 for _ in range(19)]
    for r, c, color in [(3, 6, 8), (4, 13, 4), (12, 14, 1), (14, 3, 2)]:
        test[r][c] = color
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            test[r + dr][c + dc] = 3
    result = transform(test)
    assert len(result) == 19 and all(len(row) == 19 for row in result)
    for row in result:
        print(' '.join(map(str, row)))
    # Explicitly exercise the known demo 3 arrangement.
    d = [[0] * 18 for _ in range(18)]
    for r, c, color in [(2, 3, 0), (7, 13, 5), (11, 7, 6), (15, 14, 4)]:
        d[r][c] = color
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            d[r + dr][c + dc] = 3
    assert len(transform(d)) == 18
    print('shape checks passed')
",
