 "content": "def transform(grid):
    """Colored centers extend rays along their rows/columns to the edges.

    The 3 markers form crosses but remain visible. Rays overwrite blank cells
    and other colors; at crossings, a center's vertical ray wins over another
    center's horizontal ray. Original 3 markers are never overwritten.
    """
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = src[r][c]
            if color not in (0, 3) and src[r-1][c] == src[r+1][c] == src[r][c-1] == src[r][c+1] == 3:
                centers.append((r, c, color))

    out = [row[:] for row in src]
    # Paint all horizontal rays first. Traverse outward from each center so
    # adjacent markers of that cross stay 3 and are not treated as barriers.
    for r, c, color in centers:
        for dc in (-1, 1):
            x = c + dc
            while 0 <= x < w:
                if src[r][x] != 3:
                    out[r][x] = color
                x += dc
    # Vertical rays overwrite horizontal rays where both cross, except 3s.
    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            while 0 <= y < h:
                if src[y][c] != 3:
                    out[y][c] = color
                y += dr
    return out

if __name__ == '__main__':
