 "content": "def transform(grid):
    """Extend crosses according to the observed ray and occlusion rule."""
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (src[r - 1][c] == 3 and src[r + 1][c] == 3
                    and src[r][c - 1] == 3 and src[r][c + 1] == 3):
                centers.append((r, c, src[r][c]))

    out = [row[:] for row in src]
    # A center sends rays through its own adjacent 3 arm, but stops at a
    # subsequent 3 along that direction. Horizontal rays are drawn first;
    # vertical rays are drawn second. Zero-valued crosses also project 0.
    for r, c, color in centers:
        for dc in (-1, 1):
            x = c + dc
            passed_arm = False
            while 0 <= x < w:
                if src[r][x] == 3:
                    if passed_arm:
                        break
                    passed_arm = True
                elif src[r][x] == 0:
                    out[r][x] = color
                x += dc

    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            passed_arm = False
            while 0 <= y < h:
                if src[y][c] == 3:
                    if passed_arm:
                        break
                    passed_arm = True
                elif src[y][c] == 0:
                    out[y][c] = color
                y += dr
    return out


